package dev.minecraftvideoplayer.web;
public final class AdminPage {
 private AdminPage(){}
 public static final String HTML="""
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Video Player Admin</title><style>body{font:14px system-ui;background:#0b0d12;color:#eee;max-width:1000px;margin:auto;padding:20px}section{background:#151923;border:1px solid #303747;border-radius:12px;padding:16px;margin:12px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}.card{padding:14px;background:#0f1219;border-radius:10px}button,input{padding:9px;border-radius:8px;border:1px solid #394150;background:#0b0d12;color:#fff}button{cursor:pointer;margin:3px}.room{border-top:1px solid #303747;padding:10px}.muted{color:#9aa3b2}pre{white-space:pre-wrap}</style></head><body><h1>Video Player Admin</h1><section><input id="token" type="password" placeholder="Admin token"><button onclick="save()">Connect</button><div class="grid"><div class="card">Web <b id="web">-</b></div><div class="card">API keys <b id="keys">-</b></div><div class="card">Port <b id="port">-</b></div><div class="card">Rooms <b id="count">-</b></div></div></section><section><button onclick="rotate()">Rotate API key</button><button onclick="saveData()">Save data</button><button onclick="reloadCfg()">Reload config</button><pre id="msg"></pre></section><section><h2>Watch Rooms</h2><div id="rooms" class="muted">Loading...</div></section><script>const $=x=>document.getElementById(x);function tok(){return localStorage.mvpAdminToken||$('token').value}async function call(p,o={}){let r=await fetch(p+'?token='+encodeURIComponent(tok()),o);if(!r.ok)throw Error(await r.text());return r.json()}async function load(){try{let x=await call('/api/admin/status');$('web').textContent=x.web;$('keys').textContent=x.youtubeKeys;$('port').textContent=x.port;$('count').textContent=x.rooms.length;$('rooms').innerHTML=x.rooms.length?x.rooms.map(r=>'<div class="room"><b>'+esc(r.room)+'</b> | Host: '+esc(r.host)+' | Viewers: '+r.viewers+' | Video: '+esc(r.video||'-')+' | '+(r.playing?'Playing':'Paused')+' <button onclick="closeRoom(\''+esc(r.room)+'\')">Close</button></div>').join(''):'No active rooms';$('msg').textContent='Connected.'}catch(e){$('msg').textContent='Error: '+e.message}}function esc(s){return String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]))}function save(){localStorage.mvpAdminToken=$('token').value;load()}async function rotate(){await call('/api/admin/rotate-key',{method:'POST'});load()}async function saveData(){await call('/api/admin/save',{method:'POST'});$('msg').textContent='Data saved.'}async function reloadCfg(){await call('/api/admin/reload',{method:'POST'});$('msg').textContent='Configuration reloaded.';load()}async function closeRoom(id){if(confirm('Close room '+id+'?')){await call('/api/admin/room/'+encodeURIComponent(id),{method:'DELETE'});load()}}$('token').value=localStorage.mvpAdminToken||'';load();setInterval(load,5000)</script></body></html>""";
}